import Foundation
import UIKit

class SessionController: UIViewController {

    @IBOutlet weak var textFieldUsername: UITextField!
    @IBOutlet weak var textFieldPassword: UITextField!

    override func viewDidLoad() {
        textFieldUsername.delegate = self
        textFieldPassword.delegate = self
    }

    override func prepare(for segue: UIStoryboardSegue, sender: Any?) {
        if segue.identifier == "logIn" {
            if let user = sender as? User {
                let controller = segue.destination as! UserViewController
                controller.user = user
            }
        }
    }

    @IBAction func logIn(_ sender: Any) {
        let username = textFieldUsername.text ?? ""
        let password = textFieldPassword.text ?? ""
        AuthManager.shared.logIn(username: username, password: password) { user, error in
            if let error = error {
                self.showAlert(message: error.localizedDescription)
            } else if let user = user {
                self.performSegue(withIdentifier: "logIn", sender: user)
            } else {
                self.showAlert(message: "Invalid User")
            }
        }
    }

    @IBAction func signUp(_ sender: Any) {
        performSegue(withIdentifier: "signUp", sender: nil)
    }
}

extension SessionController: UITextFieldDelegate {
    func textFieldShouldReturn(_ textField: UITextField) -> Bool {
        textField.resignFirstResponder()
        return true
    }
}
