    private let baseURL = "http://192.168.1.16:3000" // TODO: replace with real URL

    private func url(for path: String) -> URL {
        guard let url = URL(string: baseURL + path) else {
            fatalError("Invalid URL: \(path)")
        }
        return url
    }

    func getUser(id: String, completion: @escaping (User?, Error?) -> Void) {
        let url = self.url(for: "/users/\(id)")
        URLSession.shared.dataTask(with: url) { data, response, error in
            guard let data = data else {
                completion(nil, error)
                return
            }
            let decoder = JSONDecoder()
            do {
                let user = try decoder.decode(User.self, from: data)
                completion(user, nil)
            } catch {
                completion(nil, error)
            }

        }.resume()
    }

    func getUsers(completion: @escaping ([User]?, Error?) -> Void) {
        let url = self.url(for: "/users")
        URLSession.shared.dataTask(with: url) { data, response, error in
            guard let data = data else {
                completion(nil, error)
                return
            }
            let decoder = JSONDecoder()
            do {
                let users = try decoder.decode([User].self, from: data)
                completion(users, nil)
            } catch {
                completion(nil, error)
            }
        }.resume()
    }

    func addUser(user: User, completion: @escaping (User?, Error?) -> Void) {
        let url = self.url(for: "/users")
        let encoder = JSONEncoder()
        do {
            let bodyData = try encoder.encode(user)
            var request = URLRequest(url: url)
            request.httpMethod = "POST"
            request.addValue("application/json", forHTTPHeaderField: "Content-Type")
            request.httpBody = bodyData
            URLSession.shared.dataTask(with: request) { data, response, error in
                guard let data = data else {
                    completion(nil, error)
                    return
                }
                let decoder = JSONDecoder()
                do {
                    let user = try decoder.decode(User.self, from: data)
                    completion(user, nil)
                } catch {
                    completion(nil, error)
                }
            }.resume()
        } catch {
            completion(nil, error)
        }
    }
}
